import sys
import math
from collections import defaultdict

MOD = 10**9 + 7

def fast_pow(base, exp, mod, res=1):
    while exp:
        if exp & 1:
            res = (res * base) % mod
        base = (base * base) % mod
        exp >>= 1
    return res

def main():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    p_mat = [[0]*n for _ in range(n)]
    index = 1
    for i in range(n):
        for j in range(n):
            p_mat[i][j] = int(data[index])
            index += 1

    inv_100 = fast_pow(100, MOD - 2, MOD)
    for i in range(n):
        for j in range(n):
            p_mat[i][j] = (p_mat[i][j] * inv_100) % MOD

    pro_mat = [[1]*(1 << n) for _ in range(n)]
    for i in range(n):
        for j in range(1 << n):
            prod = 1
            for k in range(n):
                if (j >> k) & 1:
                    prod = (prod * p_mat[i][k]) % MOD
                else:
                    prod = (prod * (MOD + 1 - p_mat[i][k])) % MOD
            pro_mat[i][j] = prod

    popcnt_arr = [bin(i).count('1') for i in range(1 << n)]
    groups = [[] for _ in range(n+1)]
    id_map = [0]*(1 << n)
    for i in range(1 << n):
        c = popcnt_arr[i]
        groups[c].append(i)
        id_map[i] = len(groups[c]) - 1

    q_vals = [[0]*(1 << n) for _ in range(1 << n)]
    for i in range(1 << n):
        for j in range(n):
            if not ((i >> j) & 1):
                q_vals[i][1 << j] = 1 << id_map[i | (1 << j)]
        for j in range(1 << n):
            q_vals[i][j] = q_vals[i][j & -j] | q_vals[i][j ^ (j & -j)]

    memo_map = {}

    def add_modulo(a, b):
        a += b
        if a >= MOD:
            a -= MOD
        return a

    def solve(index, state):
        if state == 0:
            return 0
        if index == n:
            return 1
        key = (index, state)
        if key in memo_map:
            return memo_map[key]
        total = 0
        subset_mask = 1
        while subset_mask < (1 << n):
            new_state = 0
            for k in range(len(groups[index])):
                if not (state & (1 << k)):
                    continue
                c = groups[index][k]
                nxt = subset_mask - (subset_mask & c)
                new_state |= q_vals[c][nxt]
            total = add_modulo(total, (pro_mat[index][subset_mask] * solve(index + 1, new_state)) % MOD)
            subset_mask += 1
        memo_map[key] = total
        return total

    print(solve(0, 1))

if __name__ == "__main__":
    main()

